<?php
requireAdmin();$title='תנועה, נטישה ומעבר למפרסם';$tz=new DateTimeZone('Asia/Jerusalem');
$from=is_string($_GET['from']??null)?$_GET['from']:date('Y-m-d',time()-29*86400);$to=is_string($_GET['to']??null)?$_GET['to']:date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$to)){$from=date('Y-m-d',time()-29*86400);$to=date('Y-m-d');}
$filters=['s.started_at>=?','s.started_at<?'];$args=[(new DateTimeImmutable($from,$tz))->getTimestamp(),(new DateTimeImmutable($to,$tz))->modify('+1 day')->getTimestamp()];
$fields=['source'=>'מקור','medium'=>'ערוץ','ad_campaign'=>'קמפיין','ad'=>'מודעה','ref'=>'REF','param'=>'PARAM','referrer_domain'=>'דומיין מפנה','language'=>'שפת כניסה'];
foreach($fields as $key=>$label){$v=$_GET[$key]??'';if(is_string($v)&&$v!==''&&strlen($v)<=253){$filters[]='s.'.$key.'=?';$args[]=$v;}}
$where=' WHERE '.implode(' AND ',$filters);$cutoff=time()-1800;
$metrics="COUNT(*) AS visits,SUM(s.views) AS views,SUM(CASE WHEN s.outbound>0 THEN 1 ELSE 0 END) AS converted,SUM(s.outbound) AS exits,SUM(CASE WHEN s.last_at<$cutoff THEN 1 ELSE 0 END) AS closed,SUM(CASE WHEN s.last_at<$cutoff AND s.views=1 AND s.engaged=0 AND s.outbound=0 THEN 1 ELSE 0 END) AS bounced";
$totals=query('SELECT '.$metrics.' FROM visit_sessions s'.$where,$args)->fetch();
$groups=query('SELECT s.source,s.medium,s.ad_campaign,s.ad,s.ref,s.param,s.referrer_domain,s.language,'.$metrics.' FROM visit_sessions s'.$where.' GROUP BY s.source,s.medium,s.ad_campaign,s.ad,s.ref,s.param,s.referrer_domain,s.language ORDER BY visits DESC LIMIT 500',$args)->fetchAll();
$percent=fn($n,$d)=>$d?number_format(100*$n/$d,1).'%':'—';
$stamp=fn($t)=>(new DateTimeImmutable('@'.$t))->setTimezone($tz)->format('d/m/Y H:i:s');
if(isset($_GET['csv'])){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="tripovela-visits.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
 fputcsv($out,['Visit ID','Entry Israel','Last activity Israel','Source','Medium','Campaign','Ad','REF','PARAM','Referrer domain','Entry language','Landing','Page views','Engaged 10s','Outbound clicks']);
 foreach(query('SELECT * FROM visit_sessions s'.$where.' ORDER BY s.started_at DESC',$args) as $row){$values=[$row['id'],$stamp($row['started_at']),$stamp($row['last_at']),$row['source'],$row['medium'],$row['ad_campaign'],$row['ad'],$row['ref'],$row['param'],$row['referrer_domain'],$row['language'],$row['landing'],$row['views'],$row['engaged'],$row['outbound']];foreach($values as &$value)if(is_string($value)&&preg_match('/^[=+@\-\t\r]/',$value))$value="'".$value;unset($value);fputcsv($out,$values);}fclose($out);return;
}
ob_start();?>
<section class="page-heading"><span class="eyebrow">TRIPOVELA · מדידת ביקורים</span><h1><?=e($title)?></h1><p>מהמודעה, דרך התוכן ועד לחיצה למפרסם.</p></section>
<nav class="admin-nav"><a href="/KNISA/">ניהול</a><a href="/KNISA/reports/">דוחות הפניות היסטוריים</a><a href="/KNISA/partners/">יצירת קישורי REF / PARAM</a><a href="/KNISA/languages/">שפות</a></nav>
<p class="notice"><?=e(uiMessage('admin.analytics.outbound_note'))?></p>
<form method="get" class="form-panel"><div class="fields"><label class="field">מתאריך — ישראל<input type="date" name="from" value="<?=e($from)?>"></label><label class="field">עד תאריך — ישראל<input type="date" name="to" value="<?=e($to)?>"></label><?php foreach($fields as $key=>$label):?><label class="field"><?=e($label)?><input name="<?=$key?>" value="<?=e(is_string($_GET[$key]??'')?($_GET[$key]??''):'')?>" maxlength="253"></label><?php endforeach?></div><button class="button">סינון</button> <button name="csv" value="1" class="button secondary">ייצוא ביקורים CSV</button></form>
<div class="result-grid"><div>ביקורים<strong><?=(int)$totals['visits']?></strong></div><div>צפיות בדפים<strong><?=(int)$totals['views']?></strong></div><div>שיעור נטישה<strong><?=$percent($totals['bounced'],$totals['closed'])?></strong></div><div>ביקורים שיצאו למפרסם<strong><?=(int)$totals['converted']?></strong></div><div>שיעור מעבר למפרסם<strong><?=$percent($totals['converted'],$totals['visits'])?></strong></div><div>לחיצות יציאה<strong><?=(int)$totals['exits']?></strong></div></div>
<p><?=e(uiMessage('admin.analytics.session_note',['count'=>(int)$totals['closed']]))?></p>
<h2>ביצועים לפי מקור, מודעה ושפה</h2><div class="table-scroll"><table><thead><tr><?php foreach(array_merge(array_values($fields),['ביקורים','צפיות','נטישה','ביקורים שיצאו','שיעור מעבר']) as $label):?><th><?=e($label)?></th><?php endforeach?></tr></thead><tbody><?php foreach($groups as $row):?><tr><?php foreach($fields as $key=>$label):?><td><?=e($row[$key]?:'לא ידוע')?></td><?php endforeach?><td><?=$row['visits']?></td><td><?=$row['views']?></td><td><?=$percent($row['bounced'],$row['closed'])?></td><td><?=$row['converted']?></td><td><?=$percent($row['converted'],$row['visits'])?></td></tr><?php endforeach?><?php if(!$groups):?><tr><td colspan="13">עדיין אין ביקורים בסינון זה.</td></tr><?php endif?></tbody></table></div>
<h2>בחירת פעילויות</h2><p>צפייה נספרת כשמחצית הכרטיס נראית; פתיחת פרטים ומעבר לספק הם אירועים נפרדים. יציאה אינה הזמנה או עמלה. מזהה המוצר מאפשר לקשר את הפעילות ליעד בקטלוג.</p><div class="table-scroll"><table><thead><tr><th>מוצר</th><th>עמוד</th><th>שפה</th><th>צפיות בכרטיס</th><th>פתיחת פרטים</th><th>יציאות לספק</th></tr></thead><tbody><?php foreach(query("SELECT a.target,a.page,a.language,SUM(a.kind='card_view'),SUM(a.kind='detail_open'),SUM(a.kind='outbound') FROM visit_actions a JOIN visit_sessions s ON s.id=a.visit_id".$where." AND a.kind IN ('card_view','detail_open','outbound') GROUP BY a.target,a.page,a.language ORDER BY COUNT(*) DESC LIMIT 200",$args) as $row):?><tr><?php foreach($row as $value):?><td><?=e($value)?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div>
<h2>איפה לוחצים</h2><p>היעד הוא נתיב באתר או מזהה כפתור. מיקום: header / footer או השליש העליון, האמצעי והתחתון של הדף, עם מספר האלמנט. אין איסוף תוכן טפסים או מחברת אישית.</p><div class="table-scroll"><table><thead><tr><th>עמוד</th><th>שפה</th><th>יעד</th><th>מיקום</th><th>לחיצות</th></tr></thead><tbody><?php foreach(query("SELECT a.page,a.language,a.target,a.placement,count(*) AS total FROM visit_actions a JOIN visit_sessions s ON s.id=a.visit_id".$where." AND a.kind='click' GROUP BY a.page,a.language,a.target,a.placement ORDER BY total DESC LIMIT 200",$args) as $row):?><tr><?php foreach($row as $value):?><td><?=e($value)?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div>
<h2>רצף האירועים — שעון ישראל</h2><div class="table-scroll"><table><thead><tr><?php foreach(['שעה','מזהה ביקור','אירוע','עמוד','שפה','מקור','דומיין כניסה','מודעה','REF','PARAM','יעד','מיקום','מפרסם'] as $label):?><th><?=e($label)?></th><?php endforeach?></tr></thead><tbody><?php foreach(query('SELECT a.at,a.visit_id,a.kind,a.page,a.language,s.source,s.referrer_domain,s.ad,s.ref,s.param,a.target,a.placement,a.provider FROM visit_actions a JOIN visit_sessions s ON s.id=a.visit_id'.$where.' ORDER BY a.id DESC LIMIT 300',$args) as $row):?><tr><?php foreach($row as $key=>$value):?><td><?=e($key==='at'?$stamp($value):($value?:'—'))?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div>
<p>מוצגות עד 500 קבוצות, 200 יעדי לחיצה ו־300 אירועים; CSV כולל את כל הביקורים בסינון. דומיין מפנה ומודעה מוצגים רק אם התקבלו: בלי UTM/REF לא ניתן לשחזר מודעה, ודפדפנים יכולים להסתיר את הדומיין. חסימת JavaScript עלולה לגרום לחוסר באירועי מעורבות ולנטישה גבוהה מדי. משתמשי ניהול, בדיקות qa_ ובוטים מוכרים מוחרגים. אין שמירת IP או טקסט שהמבקר הקליד.</p>
<?php $content=ob_get_clean();require ROOT.'/views/layout.php';
